from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    rows = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    cols = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    source = None
    for a, b in rows:
        for x, y in cols:
            panel = [[grid[r][c] for c in range(x, y)] for r in range(a, b)]
            if any(v != bg for row in panel for v in row):
                source = panel
                break
        if source is not None:
            break
    if source is None:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    for a, b in rows:
        for x, y in cols:
            for r in range(a, b):
                for c in range(x, y):
                    out[r][c] = source[(r - a) % len(source)][(c - x) % len(source[0])]
    return out
